set-variable.value:
@{
    try {
      var keyEnabled = "{{caller-key-enabled}}";
      var entraEnabled = "{{caller-entra-enabled}}";
      var oktaEnabled = "{{caller-okta-enabled}}";
      foreach (var flag in new[] { keyEnabled, entraEnabled, oktaEnabled }) {
        if (flag != "true" && flag != "false") { return false; }
      }
      if ("{{caller-configuration-valid}}" != "true" || (keyEnabled != "true" && entraEnabled != "true" && oktaEnabled != "true")
          || "{{caller-native-subscription-required}}" != keyEnabled
          || !System.Text.RegularExpressions.Regex.IsMatch("{{caller-jwt-product-id}}", @"\A[A-Za-z0-9_-]{1,80}\z")) { return false; }
      if (entraEnabled == "true") {
        Guid tenant;
        Guid audience;
        if (!Guid.TryParse("{{caller-entra-tenant-id}}", out tenant) || tenant == Guid.Empty
            || !Guid.TryParse("{{api-audience}}", out audience) || audience == Guid.Empty) { return false; }
        var issuer = "{{caller-entra-issuer}}";
        var suffix = "/" + tenant.ToString() + "/v2.0";
        var expectedHost = "{{caller-entra-login-host}}";
        if (expectedHost != "login.microsoftonline.com" && expectedHost != "login.microsoftonline.us") { return false; }
        if (issuer != "https://" + expectedHost + suffix || "{{entra-openid-config-url}}" != issuer + "/.well-known/openid-configuration"
            || !System.Text.RegularExpressions.Regex.IsMatch("{{required-scope}}", @"\A[A-Za-z0-9._-]+\z")) { return false; }
        var clients = "{{caller-entra-client-ids}}";
        if (clients != "__any__") {
          foreach (var allowed in clients.Split(',')) {
            Guid client;
            if (!Guid.TryParse(allowed.Trim(), out client) || client == Guid.Empty || client == audience) { return false; }
          }
        }
      }
      if (oktaEnabled == "true") {
        var issuerText = "{{caller-okta-issuer}}";
        var issuer = new Uri(issuerText);
        if (issuer.Scheme != "https" || issuer.Port != 443
            || !string.IsNullOrEmpty(issuer.UserInfo) || !string.IsNullOrEmpty(issuer.Query) || !string.IsNullOrEmpty(issuer.Fragment)
            || !System.Text.RegularExpressions.Regex.IsMatch(issuer.AbsolutePath, @"\A/oauth2/[A-Za-z0-9_-]+\z")
            || issuer.IsLoopback || issuer.Host.EndsWith(".invalid", StringComparison.OrdinalIgnoreCase)
            || issuerText == "{{caller-entra-issuer}}"
            || "{{caller-okta-openid-config-url}}" != issuerText + "/.well-known/openid-configuration"
            || string.IsNullOrWhiteSpace("{{caller-okta-audience}}") || "{{caller-okta-audience}}" == "__none__"
            || !System.Text.RegularExpressions.Regex.IsMatch("{{caller-okta-required-scope}}", @"\A[A-Za-z0-9._-]+\z")) { return false; }
        var clients = "{{caller-okta-client-ids}}";
        if (clients == "__none__" || clients == "__any__") { return false; }
        foreach (var client in clients.Split(',')) {
          if (!System.Text.RegularExpressions.Regex.IsMatch(client.Trim(), @"\A[A-Za-z0-9_-]+\z") || client.Trim() == "{{caller-okta-audience}}") { return false; }
        }
      }
      return true;
    } catch { return false; }
  }

@{
    if (!context.Variables.ContainsKey("byokConfigurationValid") || !(bool)context.Variables["byokConfigurationValid"]) { return "invalid"; }
    var keyHeader = (string)context.Variables["byokCredentialHeader"];
    if (keyHeader != "api-key" && keyHeader != "x-api-key") { return "invalid"; }
    var otherHeader = keyHeader == "api-key" ? "x-api-key" : "api-key";
    var headers = context.Request.Headers;
    var query = context.Request.OriginalUrl.Query;
    var hasKey = headers.ContainsKey(keyHeader);
    var hasBearer = headers.ContainsKey("Authorization");
    var hasQueryKey = query.ContainsKey("api-key");
    var sources = (hasKey ? 1 : 0) + (hasBearer ? 1 : 0) + (hasQueryKey ? 1 : 0);
    if (sources != 1 || headers.ContainsKey(otherHeader) || headers.ContainsKey("Ocp-Apim-Subscription-Key")
        || query.ContainsKey("subscription-key") || query.ContainsKey("x-api-key")
        || query.ContainsKey("Authorization") || query.ContainsKey("access_token")) { return "invalid"; }
    var values = hasKey ? headers[keyHeader] : (hasBearer ? headers["Authorization"] : query["api-key"]);
    if (values.Length != 1 || string.IsNullOrWhiteSpace(values[0]) || values[0].Contains(",")
        || values[0].Contains("\r") || values[0].Contains("\n")) { return "invalid"; }
    var keyEnabled = "{{caller-key-enabled}}" == "true";
    if (keyEnabled && "{{caller-native-subscription-required}}" != "true") { return "invalid"; }
    var jwtEnabled = "{{caller-entra-enabled}}" == "true" || "{{caller-okta-enabled}}" == "true";
    var openProduct = context.Product != null && context.Product.Id == "{{caller-jwt-product-id}}";
    var nativeKey = keyEnabled && context.Subscription != null && !openProduct;
    if (hasQueryKey) { return nativeKey ? "key-query" : "invalid"; }
    if (hasBearer) {
      if (!jwtEnabled || nativeKey || !values[0].StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase)
          || string.IsNullOrWhiteSpace(values[0].Substring(7))) { return "invalid"; }
      return "jwt-bearer";
    }
    if (nativeKey) { return "key-header"; }
    return jwtEnabled ? "jwt-header" : "invalid";
  }
